"""읽기·근거 선택·판단을 연결하는 게임 내부 조사 화면."""
import json
from investigation_content import CASES
JS = "\nconst IQ_STATE={};\nfunction iqState(i){return IQ_STATE[i]||(IQ_STATE[i]={seen:[],selected:[],choice:'',view:null,done:false,error:'',hints:0,tries:0});}\nfunction iqMark(t){return esc(t).replace(/(\\d+번 거래)/g,'<b style=\"background:#FFE08A;color:#6B4300;padding:2px 8px;border-radius:8px;white-space:nowrap;font-weight:900\">🏷️ $1</b>');}\nfunction iqHTML(i){\n const c=IQ_CASES[i],s=iqState(i);\n const source=c.sources.find(x=>x[0]===s.view);\n return `<section class=\"box\" style=\"border:2px solid #b9d2c7;border-radius:16px;padding:16px;margin:12px 0;overflow-wrap:anywhere\">\n <h3>${esc(c.title)}</h3><p>자료를 찾아 읽고, 서로 연결되는 근거를 골라 결론을 제출하세요. 정답 자료를 처음부터 모두 보여 주지는 않아요.</p>\n <div style=\"display:flex;gap:8px;flex-wrap:wrap\">${c.sources.map(x=>`<button onclick=\"iqOpen(${i},'${x[0]}')\" ${x[3]&&!s.seen.includes(x[3])?'disabled':''}>${s.seen.includes(x[0])?'✓ ':''}${iqMark(x[1])}${x[3]&&!s.seen.includes(x[3])?' · 앞선 자료 확인 후':''}</button>`).join('')}</div>\n ${source?`<article style=\"background:#f0f5f2;padding:14px;margin:12px 0;border-left:5px solid #39756b\"><b style=\"font-size:1.05rem\">${iqMark(source[1])}</b><p style=\"font-size:1.05rem;line-height:1.75;margin:.5rem 0 0\">${iqMark(source[2])}</p></article>`:''}\n ${s.done?`<p style=\"background:#dff1e5;padding:12px\"><b>✓ 근거 연결 완료</b><br>${esc(c.lesson)}</p>`:`\n <p><b>${esc(c.question)}</b></p>\n <select aria-label=\"조사 ${i+1} 결론\" onchange=\"iqState(${i}).choice=this.value;render()\" style=\"width:100%;font:inherit;padding:10px;white-space:normal\"><option value=\"\">결론 선택</option>${c.options.map((v,k)=>`<option value=\"${k}\" ${String(k)===s.choice?'selected':''}>${esc(v)}</option>`).join('')}</select>\n ${s.choice!==''?'<p><b>선택한 결론:</b> '+esc(c.options[Number(s.choice)])+'</p>':''}\n <p><b>이 결론을 직접 뒷받침하는 자료 ${c.proof.length}개 선택</b></p>\n ${s.seen.length?c.sources.filter(x=>s.seen.includes(x[0])).map(x=>`<label style=\"display:block;padding:8px\"><input type=\"checkbox\" ${s.selected.includes(x[0])?'checked':''} onchange=\"iqSelect(${i},'${x[0]}',this.checked)\"> ${iqMark(x[1])}</label>`).join(''):'<p>먼저 위의 자료를 조사하세요.</p>'}\n <button onclick=\"iqCheck(${i})\">근거와 결론 제출</button> <button onclick=\"iqHint(${i})\">비교할 지점 힌트</button>\n <p role=\"status\" style=\"color:#9b361d;font-weight:700\">${esc(s.error)}</p>\n ${s.hints?`<p>💡 ${esc(c.hint)}</p>`:''}`}\n </section>`;\n}\nfunction iqOpen(i,k){const c=IQ_CASES[i],s=iqState(i),x=c.sources.find(x=>x[0]===k);if(!x||(x[3]&&!s.seen.includes(x[3])))return;if(!s.seen.includes(k))s.seen.push(k);s.view=k;render();}\nfunction iqSelect(i,k,on){const s=iqState(i);s.selected=s.selected.filter(x=>x!==k);if(on&&s.seen.includes(k))s.selected.push(k);}\nfunction iqHint(i){iqState(i).hints++;if(typeof iqHintUsed==='function')iqHintUsed(i);render();}\nfunction iqCheck(i){const s=iqState(i),c=IQ_CASES[i];if(s.done)return;\n if(s.choice===''||s.selected.length!==c.proof.length){s.error='결론과 필요한 수의 근거를 모두 선택하세요.';render();return;}\n s.tries++;\n const ok=Number(s.choice)===c.answer&&c.proof.every(k=>s.seen.includes(k)&&s.selected.includes(k));\n if(ok){s.done=true;s.error='';iqComplete(i);}\n else{s.error='아직 근거가 결론을 충분히 뒷받침하지 못해요. 자료의 대상·거래번호·확인 경로를 다시 비교하세요.';if(typeof iqWrong==='function')iqWrong(i);render();}\n}\nfunction iqReset(){for(const k of Object.keys(IQ_STATE))delete IQ_STATE[k];}\n"
def attach(html):
    payload=json.dumps(CASES,ensure_ascii=False).replace("<","\\u003c")
    return html.replace("<script>", "<script>\nconst IQ_CASES="+payload+";\n"+JS+"\n",1)
